/**
 * @summary Transcribe a recording using an explicitly selected cloud provider
 */
export const transcribeWithProvider = async (provider: 'groq' | 'xai',
    cloudTranscriptionInput: CloudTranscriptionInput, options?: Parameters<typeof customFetch>[1]): Promise<TranscriptionResult> => {
    const formData = new FormData();
formData.append(`file`, cloudTranscriptionInput.file);
formData.append(`confirmExternalProcessing`, cloudTranscriptionInput.confirmExternalProcessing.toString())
if(cloudTranscriptionInput.language !== undefined) {
 formData.append(`language`, cloudTranscriptionInput.language);
 }
if(cloudTranscriptionInput.studentNames !== undefined) {
 cloudTranscriptionInput.studentNames.forEach(value => formData.append(`studentNames`, value));
 }
if(cloudTranscriptionInput.diarize !== undefined) {
 formData.append(`diarize`, cloudTranscriptionInput.diarize.toString())
 }

  return customFetch<TranscriptionResult>(getTranscribeWithProviderUrl(provider),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





